float gear(vec3 p,float r) {
    float n = 12.;
    p = radialRepeat(p,n);
    return max(min(roundBox(p,vec3(0,0,.02),r*.4),roundBox(p-vec3(r*.1,0,0),vec3(r*.11,r*.02,.02),.01)),-roundBox(p,vec3(0,0,.1),r*.3));
}
vec4 gear (vec3 p, mat3 m, float r,float s) {
    p *= m;
    p.z -= .3;
    p.xy *= ei(s*iTime+1.*3.14159*(.5+.5*s)/12.);
    return vec4(gear(p,r),p);
}
float mino (float d, vec4 g, inout vec3 o) {
    if (g.x<d) {
        d = g.x;
        o = g.yzw;
    }
    return d;
}
#define phi 1.618
vec4 map (vec3 p) {
    float d = 1e4;
    //d = length(p)-.3;

    vec3 o = p;

    //d = max(d,abs(dot(p,normalize(vec3(0,+1,0))))-.2);
    float s = 1.;
    mat3 g = mat3(1);
    vec3 x = vec3(1,0,0);
    vec3 y = vec3(0,1,0);
    vec3 z = vec3(0,0,1);
    d = mino(d,gear(p,mat3(x,z,y),1.1,1.),o);
    d = mino(d,gear(p,mat3(x,z,-y),1.1,-1.),o);

    for (float i = 0.; i < 5.; i++) {
        g[0].xz*=ei(3.14159*2./5.);
        g[1].xz*=ei(3.14159*2./5.);
        g[2].xz*=ei(3.14159*2./5.);
        d = mino(d,gear(p,g,1.,-1.),o);

    }
    float T = phi;
    for (float i = 0.; i < 5.; i++) {
        vec3 g = normalize(vec3(phi,1,0));
         g.xz *= ei(i*3.14159*2./5.);
         //d = max(d,dot(p,s)-.2);
         mat3 m = mat3(1);



         m[0].yz*=ei(.5*3.14159*T);
         m[1].yz*=ei(.5*3.14159*T);
         m[2].yz*=ei(.5*3.14159*T);

         m[0].xz*=ei(i*3.14159*2./5.);
         m[1].xz*=ei(i*3.14159*2./5.);
         m[2].xz*=ei(i*3.14159*2./5.);

         d = mino(d,gear(p,m,1.,1.),o);
         s *= -1.;
    }
    for (float i = 0.; i < 5.; i++) {
        vec3 g = normalize(vec3(phi,1,0));
         g.xz *= ei(i*3.14159*2./5.);
         //d = max(d,dot(p,s)-.2);
         mat3 m = mat3(1);


         m[0].yz*=ei(-.5*3.14159*T);
         m[1].yz*=ei(-.5*3.14159*T);
         m[2].yz*=ei(-.5*3.14159*T);

         m[0].xz*=ei(i*3.14159*2./5.);
         m[1].xz*=ei(i*3.14159*2./5.);
         m[2].xz*=ei(i*3.14159*2./5.);

         d = mino(d,gear(p,m,1.,1.),o);
         s *= -1.;
    }


    return vec4(d,o);
}
vec3 normal (vec3 p) {
    vec2 e = vec2(1e-4,0);
    float m = map(p).x;
    return normalize(vec3(
        map(p+e.xyy).x-m,
        map(p+e.yxy).x-m,
        map(p+e.yyx).x-m
    ));

}
